import numpy as np
rng = np.random.default_rng(0)
x0 = rng.normal(size=(500, 256))
def signal(std):
    x, out = x0, []
    for layer in range(1, 21):
        x = np.maximum(0, x @ rng.normal(0, std, size=(256, 256)))
        if layer in (1, 10, 20):
            out.append(f"{x.std():.1e}")
    return out
for name, std in [("too small, 0.01", 0.01), ("He, sqrt(2/256)", np.sqrt(2 / 256)), ("too large, 0.15", 0.15)]:
    print(f"{name:16}", signal(std))
